const serviceList = (state) => (state.services || []).filter((service) => service?.name).slice(0, 6);
const displayServices = (state) => {
  const services = serviceList(state);
  return services.length ? services : [{ name: '서비스를 추가하세요', description: '편집기에서 서비스 이름과 설명을 입력할 수 있습니다.', price: '—' }];
};
const value = (state, key, fallback = '') => escapeHtml(state[key] || fallback);
const service = (item, key, fallback = '') => escapeHtml(item?.[key] || fallback);
const number = (index, length = 2) => String(index + 1).padStart(length, '0');
const initials = (name) => String(name || 'L100').replace(/[^A-Za-z0-9가-힣]/g, '').slice(0, 2).toUpperCase();

function documentShell(state, template, design, body, themeCss) {
  const font = FONT_STACKS[state.font] || FONT_STACKS[design.defaultFont] || FONT_STACKS.sans;
  const title = escapeHtml(state.businessName || template.name);
  const cssVariables = `--primary:${state.primary};--secondary:${state.secondary};--background:${state.background};--ink:${state.ink};--font:${font};`;
  return `<!doctype html>
<html lang="ko">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>${title} · Launch100 Preview</title>
<style>
*{box-sizing:border-box}html{scroll-behavior:smooth;overflow-x:clip}body{margin:0;min-width:280px;color:var(--ink);background:var(--background);font-family:var(--font);overflow-x:clip}button,a,input{font:inherit}a{color:inherit;text-decoration:none}button{color:inherit}.site{min-height:100vh;overflow-x:clip}.sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.eyebrow{font-size:9px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.cta{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:10px 15px;font-size:10px;font-weight:900}.footer-base{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:26px clamp(18px,5vw,70px);font-size:9px}.footer-base span{opacity:.62}@media(max-width:720px){.footer-base{align-items:flex-start;flex-direction:column}}
${themeCss}
</style>
</head>
<body style="${cssVariables}" data-design-id="${template.id}" data-design-family="${design.family}" data-layout-signature="${design.signature}" data-nav-style="${design.nav}" data-card-style="${design.cards}">
${body}
</body>
</html>`;
}

function contactRows(state, labels = {}) {
  const rows = [
    [labels.address || '주소', value(state, 'address', '주소를 입력하세요')],
    [labels.phone || '전화', value(state, 'phone', '전화번호를 입력하세요')],
    [labels.email || '이메일', value(state, 'email', '이메일을 입력하세요')],
    [labels.weekday || '평일', value(state, 'weekdayHours', '운영시간을 입력하세요')],
    [labels.weekend || '주말', value(state, 'weekendHours', '운영시간을 입력하세요')]
  ];
  return rows.map(([label, content]) => `<div><dt>${escapeHtml(label)}</dt><dd>${content}</dd></div>`).join('');
}

